import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"插入与归并","description":"","frontmatter":{"title":"插入与归并","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/insertion-merge.md","filePath":"cs/insertion-merge.md","lastUpdated":1789023840000}'),p={name:"cs/insertion-merge.md"};function m(E,a,_,u,T,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="插入与归并" tabindex="-1">插入与归并 <a class="header-anchor" href="#插入与归并" aria-label="Permalink to &quot;插入与归并&quot;">​</a></h1><div class="epigraph"><p>插入把已排序前缀一次延长一个元素；归并把两个已排序序列线性扫成一条。</p><footer>—— 据 Knuth, The Art of Computer Programming, vol. 3, Sorting and Searching；CLRS 第 2 章整理</footer></div><p>上一课<a href="/cs/binary-search">二分查找</a>钉了分解–递归–合并。<a href="/cs/loop-invariant">循环不变式</a>钉了前缀扩大。本课不重讲这两套骨架。缺口是：排序作为第一份具体算法，需要同时看见<strong>迭代的插入</strong>和<strong>分治的归并</strong>，否则后课堆排、快排没有对照。本课只处理比较排序里这两端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无序数组要变成非降序列。插入：第 \\(i\\) 轮开始时 \\(A[1..i-1]\\) 已排序，把 \\(A[i]\\) 插进正确位置。不变式就是这条前缀。最坏每次挪 \\(i\\) 格，\\(\\Theta(n^2)\\)。归并：对半切开，递归排序，再用 \\(\\Theta(n)\\) 双指针合并。主定理情形二给出 \\(\\Theta(n\\log n)\\)。</p><p>缺口不是「什么是排序」，而是这两套正确性与代价必须并排：一个用循环不变式，一个用分治归纳。稳定性：相等键相对次序，插入与归并都可以稳定；后课堆排默认不稳。</p><h3 id="归并不是插入的加速版" tabindex="-1">归并不是插入的加速版 <a class="header-anchor" href="#归并不是插入的加速版" aria-label="Permalink to &quot;归并不是插入的加速版&quot;">​</a></h3><p>插入几乎不占额外数组；归并通常要 \\(\\Theta(n)\\) 缓冲。近乎有序时插入是 \\(\\Theta(n)\\)，归并仍是 \\(\\Theta(n\\log n)\\)。没有「永远更快」这一方。Knuth 把两者都当作内排的基本动作，外存归并另算块 I/O，本课不展开。</p><p><span class="marginnote">冯·诺依曼 1945 年前后的归并程序是分治排序的源头之一。CLRS 用插入练不变式、用归并练递归。本课保持这个分工。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入：从左到右，内层把大于键的元素右移。终止时 \\(i=n+1\\)，整表有序。归并：<code>sort(L); sort(R); merge(L,R)</code>。<code>merge</code> 的不变式是：输出前缀已是两输入前缀的有序合并，指针只前进。</p>',11)),(e(),s(c,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E6%97%A0%E5%BA%8F%E6%95%B0%E7%BB%84%22%5D%20--%3E%20INS%5B%22%E6%8F%92%E5%85%A5%EF%BC%9A%E5%89%8D%E7%BC%80%E4%B8%8D%E5%8F%98%E5%BC%8F%22%5D%0A%20%20ARR%20--%3E%20MS%5B%22%E5%BD%92%E5%B9%B6%EF%BC%9A%E5%AF%B9%E5%8D%8A%20%2B%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20INS%20--%3E%20N2%5B%22%CE%98(n%C2%B2)%20%E6%9C%80%E5%9D%8F%22%5D%0A%20%20MS%20--%3E%20NL%5B%22%CE%98(n%20log%20n)%20%E6%9C%80%E5%9D%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>比较只在键之间进行。后课线性时间排序会动用值域，本课仍在比较模型里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>插入的内层是线性搜索或（折半找位置仍要挪元素）\\(\\Theta(n^2)\\) 移动下界在最坏数据上仍在。归并的深度 \\(\\Theta(\\log n)\\)，每层总合并 \\(\\Theta(n)\\)。额外空间与缓存行为不同：插入紧凑，归并扫两段再写回，<a href="/cs/locality-principle">局部性</a>上各有利弊，本课不量化 Cache。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证比较排序的 \\(\\Omega(n\\log n)\\)，那是<a href="/cs/sort-lower-bound">下界</a>。不引入堆。不处理链表归并的指针版——表示已在<a href="/cs/linked-list-locality">链表</a>，算法骨架相同。也不把 Timsort 的 run 探测写进来，那是工程附录。</p><p>后课默认：插入 = 前缀不变式 + \\(\\Theta(n^2)\\)；归并 = 分治 + \\(\\Theta(n\\log n)\\) + 线性额外空间。堆排序用<a href="/cs/heap-priority">堆</a>换掉缓冲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>插入用循环不变式，最坏平方；近乎有序则线性。</li><li>归并用分治，最坏 \\(n\\log n\\)，通常要线性额外空间。</li><li>两者都可以稳定；对照的是骨架与资源，不是「谁过时」。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 2 章。</li></ul>',8))])}const A=n(p,[["render",m]]);export{B as __pageData,A as default};
